function ReadOnlyCourses({ role, go }) {
  const [rows, setRows] = useState([]);
  const [selectedId, setSelectedId] = useState(() => getActiveCourseId());
  const [trainees, setTrainees] = useState([]);
  const [reports, setReports] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [workdays, setWorkdays] = useState({ trainingDaysCount: 0 });
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const [err, setErr] = useState("");
  const today = todayStr();
  const selected = rows.find(course => course.courseId === selectedId) || null;
  useEffect(() => {
    setLoading(true); setErr("");
    apiGet(role === "trainee" ? "/me/courses" : "/courses")
      .then(v => {
        const list = Array.isArray(v) ? v : [];
        setRows(list);
        const active = getActiveCourseId();
        const next = list.some(course => course.courseId === active) ? active : (list[0]?.courseId || "");
        setSelectedId(next);
        if (next) setActiveCourseId(next);
      })
      .catch(e => setErr(e?.errorMessage || e?.message || String(e)))
      .finally(() => setLoading(false));
  }, [role]);
  useEffect(() => {
    if (!selectedId || role === "trainee") return;
    let alive = true;
    setDetailLoading(true); setErr("");
    Promise.all([
      apiGet(`/courses/${selectedId}/trainees`).catch(() => []),
      apiGet(`/reports?date=${today}`).catch(() => []),
      apiGet(`/attendance?date=${today}`).catch(() => []),
      apiGet(`/courses/${selectedId}/workdays?month=${today.slice(0, 7)}`).catch(() => ({ trainingDaysCount: 0 })),
    ]).then(([studentRows, reportRows, attendanceRows, workdayData]) => {
      if (!alive) return;
      const members = Array.isArray(studentRows) ? studentRows : [];
      const ids = new Set(members.map(student => student.userId || student.id));
      setTrainees(members);
      setReports((Array.isArray(reportRows) ? reportRows : []).filter(report => ids.has(report.traineeId || report.userId)));
      setAttendance((Array.isArray(attendanceRows) ? attendanceRows : []).filter(item => ids.has(item.traineeId || item.userId)));
      setWorkdays(workdayData || { trainingDaysCount: 0 });
    }).finally(() => alive && setDetailLoading(false));
    return () => { alive = false; };
  }, [selectedId, role, today]);
  function chooseCourse(id) { setSelectedId(id); setActiveCourseId(id); }
  const roleTitle = role === "instructor" ? "担当コース" : role === "client" ? "参加コース" : "所属コース";
  const roleDesc = role === "instructor" ? "担当コースを切り替え、授業準備と受講生対応へ進みます" : role === "client" ? "自社受講生が参加するコースの状況を確認します" : "自分の所属コースを確認します";
  const traineeIds = new Set(trainees.map(student => student.userId || student.id));
  const missingReports = Math.max(trainees.length - new Set(reports.map(report => report.traineeId || report.userId)).size, 0);
  const missingAttendance = Math.max(trainees.length - new Set(attendance.map(item => item.traineeId || item.userId)).size, 0);
  return (
    <div>
      <SectionHead title={roleTitle} desc={roleDesc} action={rows.length > 0 ? <select value={selectedId} onChange={e => chooseCourse(e.target.value)} className="min-w-56 rounded-xl px-3 py-2 text-sm font-semibold outline-none" style={{ border: `1px solid ${T.border}`, color: T.textPrimary, background: T.bgSurface }}>{rows.map(course => <option key={course.courseId} value={course.courseId}>{course.name || course.courseId}</option>)}</select> : null} />
      {err && <div className="mb-3 rounded-xl px-3 py-2 text-sm" style={adminErrStyle}>{err}</div>}
      {loading ? <Card><SkeletonRows rows={4} /></Card>
        : !selected ? <Card><EmptyState title="コースがありません" desc="表示できるコースがありません" /></Card>
        : <div className="space-y-5">
          <Card className="p-5">
            <div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="text-base font-bold" style={{ color: T.textPrimary }}>{selected.name || selected.courseId}</h3><Badge tone={kindTone(selected.type || selected.kind)}>{kindLabel(selected.type || selected.kind)}</Badge></div><p className="mt-1 max-w-3xl text-sm leading-relaxed" style={{ color: T.textSecondary }}>{selected.description || selected.memo || "コース説明は未登録です。"}</p></div>{Array.isArray(selected.instructorIds) && <Badge tone={selected.instructorIds.length ? "cyan" : "amber"}>担当講師 {selected.instructorIds.length}名</Badge>}</div>
          </Card>
          {role !== "trainee" && <>
            {detailLoading ? <Card><SkeletonRows rows={4} /></Card> : <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Users} label="所属受講生" value={`${trainees.length}名`} /><Stat icon={NotebookPen} label="本日の日報未保存" value={`${missingReports}名`} tone={missingReports ? "amber" : "green"} /><Stat icon={Clock} label="本日の勤怠未登録" value={`${missingAttendance}名`} tone={missingAttendance ? "amber" : "green"} /><Stat icon={Calendar} label="今月の研修日" value={`${workdays.trainingDaysCount || 0}日`} tone="cyan" /></div>}
            <Card className="p-5"><div className="mb-3"><h3 className="font-bold" style={{ color: T.textPrimary }}>このコースで行うこと</h3><p className="text-xs" style={{ color: T.textMuted }}>コース選択を保ったまま、必要な管理画面へ移動します。</p></div><div className="flex flex-wrap gap-2"><Btn kind="soft" size="sm" icon={Calendar} onClick={() => go?.("curriculum")}>カリキュラム</Btn><Btn kind="ghost" size="sm" icon={NotebookPen} onClick={() => go?.("reports")}>日報</Btn><Btn kind="ghost" size="sm" icon={Clock} onClick={() => go?.("attendance")}>勤怠</Btn><Btn kind="ghost" size="sm" icon={ClipboardCheck} onClick={() => go?.("tests")}>テスト</Btn><Btn kind="ghost" size="sm" icon={FileText} onClick={() => go?.("materials")}>研修資料</Btn><Btn kind="ghost" size="sm" icon={Users} onClick={() => go?.("trainees")}>受講生</Btn></div></Card>
            <Card className="overflow-hidden"><div className="flex items-center justify-between gap-2 p-4" style={{ borderBottom: `1px solid ${T.border}` }}><div><h3 className="font-bold" style={{ color: T.textPrimary }}>所属受講生</h3><p className="text-xs" style={{ color: T.textMuted }}>選択コースに所属する受講生</p></div><Badge tone="cyan">{traineeIds.size}名</Badge></div>{detailLoading ? <SkeletonRows rows={3} /> : trainees.length === 0 ? <div className="px-4 py-8 text-center text-sm" style={{ color: T.textMuted }}>所属受講生はいません。</div> : <div className="grid gap-2 p-4 md:grid-cols-2">{trainees.slice(0, 8).map(student => <div key={student.userId || student.id} className="flex items-center gap-2 rounded-xl p-3" style={{ background: T.bgBase }}><Avatar name={student.name || student.email} size={32} /><div className="min-w-0"><div className="truncate text-sm font-semibold" style={{ color: T.textPrimary }}>{student.name || "氏名未設定"}</div><div className="truncate text-xs" style={{ color: T.textMuted }}>{student.email || student.userId}</div></div></div>)}</div>}</Card>
          </>}
        </div>}
    </div>
  );
}

